/**
 * GUIKit Memory Checker
 * 
 * Evaluates memory requirements for GUI JSON files
 * Checks if GUI can fit in available memory before loading
 * Displays error messages on TFT if memory is insufficient
 * 
 * Generated by Mistral Vibe
 * Date: 2026-08-15
 */

#ifndef GUI_MEMORY_CHECKER_H
#define GUI_MEMORY_CHECKER_H

#include <stdint.h>
#include <stdbool.h>
#include "widget_pool.h"
#include "renderer.h"

// Forward declaration for TFT_ST7789 (defined in esp8266_expander_ram_tft.cpp)
class TFT_ST7789;

// ============================================================================
// Memory Requirements per Widget Type (in bytes)
// ============================================================================

// Base widget size (without children pointer array)
#define MEMORY_BASE_WIDGET_SIZE sizeof(Widget)

// Widget type sizes
#define MEMORY_WIDGET_BUTTON_SIZE sizeof(WidgetButton)
#define MEMORY_WIDGET_LABEL_SIZE sizeof(WidgetLabel)
#define MEMORY_WIDGET_SLIDER_SIZE sizeof(WidgetSlider)
#define MEMORY_WIDGET_VIEW_SIZE sizeof(WidgetView)
#define MEMORY_WIDGET_TEXT_INPUT_SIZE (sizeof(Widget) + 512)  // Includes text buffer
#define MEMORY_WIDGET_TEXT_EDITOR_SIZE (sizeof(Widget) + 4096) // Includes large text buffer

// Additional memory for children (per child pointer)
#define MEMORY_PER_CHILD_POINTER sizeof(Widget*)

// Children array overhead (when children are added)
#define MEMORY_CHILDREN_ARRAY_START 4  // Initial capacity
#define MEMORY_CHILDREN_ARRAY_INCREMENT 4

// ============================================================================
// Memory Configuration
// ============================================================================

// Available memory for widgets (configurable)
// This should match the pool sizes in widget_pool.h
#define AVAILABLE_WIDGETS MAX_WIDGETS
#define AVAILABLE_BUTTONS MAX_BUTTONS
#define AVAILABLE_LABELS MAX_LABELS
#define AVAILABLE_SLIDERS MAX_SLIDERS
#define AVAILABLE_VIEWS MAX_VIEWS
#define AVAILABLE_TEXT_INPUTS 8
#define AVAILABLE_TEXT_EDITORS 4

// Total available memory for GUI (in bytes)
// ESP8266 has ~80KB free heap (varies), we reserve 64KB for GUI
#define TOTAL_AVAILABLE_GUI_MEMORY (64 * 1024)

// Minimum free memory threshold (bytes)
#define MIN_FREE_MEMORY_THRESHOLD 4096

// ============================================================================
// Memory Statistics Structure
// ============================================================================

typedef struct {
    uint16_t widget_count;
    uint16_t button_count;
    uint16_t label_count;
    uint16_t slider_count;
    uint16_t view_count;
    uint16_t text_input_count;
    uint16_t text_editor_count;
    uint16_t total_children;
    uint32_t total_memory_bytes;
    uint32_t estimated_json_size;
    bool fits_in_memory;
    const char* error_message;
} GuiMemoryStats;

// ============================================================================
// Function Declarations
// ============================================================================

/**
 * Initialize memory checker
 * Must be called before any memory checking
 */
void gui_memory_checker_init(void);

/**
 * Get current memory usage from widget pools
 * 
 * @return GuiMemoryStats with current usage
 */
GuiMemoryStats gui_memory_get_current_usage(void);

/**
 * Calculate memory required for a GUI from JSON string
 * 
 * @param json GUI JSON string to analyze
 * @return GuiMemoryStats with estimated memory requirements
 */
GuiMemoryStats gui_memory_calculate_from_json(const char* json);

/**
 * Calculate memory required for a GUI from file
 * 
 * @param filepath Path to GUI JSON file
 * @return GuiMemoryStats with estimated memory requirements
 */
GuiMemoryStats gui_memory_calculate_from_file(const char* filepath);

/**
 * Check if a GUI can be loaded based on its JSON
 * 
 * @param json GUI JSON string
 * @param available_memory Available memory in bytes
 * @return true if GUI can fit, false otherwise
 */
bool gui_memory_can_fit(const char* json, uint32_t available_memory);

/**
 * Check if a GUI file can be loaded
 * 
 * @param filepath Path to GUI JSON file
 * @return true if GUI can fit, false otherwise
 */
bool gui_memory_can_fit_file(const char* filepath);

/**
 * Display memory error message on TFT
 * 
 * @param tft TFT display instance
 * @param stats Memory statistics (for detailed error info)
 */
void gui_memory_display_error(TFT_ST7789* tft, const GuiMemoryStats* stats);

/**
 * Display a simple out-of-memory error on TFT
 * 
 * @param tft TFT display instance
 * @param message Custom error message (can be NULL for default)
 */
void gui_memory_display_oom_error(TFT_ST7789* tft, const char* message);

/**
 * Get human-readable memory size string
 * 
 * @param bytes Number of bytes
 * @return String representation (e.g., "4.5 KB")
 */
const char* gui_memory_format_size(uint32_t bytes);

// ============================================================================
// Helper Macros
// ============================================================================

// Check if memory is available for a specific widget type
#define GUI_MEMORY_HAS_WIDGETS() (pool_get_allocated_count(WIDGET_TYPE_VIEW) < pool_get_capacity(WIDGET_TYPE_VIEW))
#define GUI_MEMORY_HAS_BUTTONS() (pool_get_allocated_count(WIDGET_TYPE_BUTTON) < pool_get_capacity(WIDGET_TYPE_BUTTON))
#define GUI_MEMORY_HAS_LABELS() (pool_get_allocated_count(WIDGET_TYPE_LABEL) < pool_get_capacity(WIDGET_TYPE_LABEL))
#define GUI_MEMORY_HAS_SLIDERS() (pool_get_allocated_count(WIDGET_TYPE_SLIDER) < pool_get_capacity(WIDGET_TYPE_SLIDER))

// Get remaining widgets of each type
#define GUI_MEMORY_REMAINING_WIDGETS() POOL_REMAINING(WIDGET_TYPE_VIEW)
#define GUI_MEMORY_REMAINING_BUTTONS() POOL_REMAINING(WIDGET_TYPE_BUTTON)
#define GUI_MEMORY_REMAINING_LABELS() POOL_REMAINING(WIDGET_TYPE_LABEL)
#define GUI_MEMORY_REMAINING_SLIDERS() POOL_REMAINING(WIDGET_TYPE_SLIDER)

#endif // GUI_MEMORY_CHECKER_H
